-- sample backup for testing
CREATE TABLE `Provinces` (`id` int NOT NULL, `Title` varchar(255) DEFAULT NULL, `API` int NOT NULL DEFAULT '0', `DetailCode` smallint DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Cities` (`id` int NOT NULL, `ProvinceID` int NOT NULL, `Title` varchar(255) DEFAULT NULL, `APICode` bigint NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `Centers` (`id` int NOT NULL, `CenterTitle` varchar(255) NOT NULL, `IsEnabled` tinyint NOT NULL DEFAULT '1', `Address` text, `Tel` varchar(255) DEFAULT NULL, `CatID` int DEFAULT NULL, `CityID` int NOT NULL, `CityTitle` varchar(255) NOT NULL, `ProvinceID` int NOT NULL, `ProvinceTitle` varchar(255) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Services` (`id` int NOT NULL, `Name` varchar(255) NOT NULL, `Short` varchar(255) NOT NULL, `SohaID` int NOT NULL, `Weight` decimal(10,1) NOT NULL DEFAULT '1.0', PRIMARY KEY (`id`));
CREATE TABLE `Education` (`id` int NOT NULL, `Name` varchar(255) DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Marriage` (`id` int NOT NULL, `Name` varchar(255) DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Roles` (`id` int NOT NULL, `Title` varchar(255) NOT NULL, `CodeName` varchar(255) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Users` (`id` int NOT NULL AUTO_INCREMENT, `NID` bigint(10) NOT NULL, `DetailCode` varchar(50) DEFAULT NULL, `Username` varchar(255) NOT NULL, `Password` varchar(255) NOT NULL, `MFA` enum('None','Authenticator','SMS','Email','Passkey') NOT NULL DEFAULT 'None', `Name` varchar(255) NOT NULL DEFAULT 'بی نام', `Family` varchar(255) NOT NULL DEFAULT 'بدون نام خانوادگی', `Father` varchar(255) NOT NULL DEFAULT '', `Gender` enum('male','female') DEFAULT NULL, `Birthday` date DEFAULT NULL, `Religion` varchar(255) NOT NULL DEFAULT '', `MarriageID` int DEFAULT '0', `EducationID` int DEFAULT NULL, `Mobile` bigint(11) NOT NULL, `Mobile2` bigint(11) DEFAULT NULL, `AreaCode` tinyint(3) DEFAULT NULL, `Phone` int(8) DEFAULT NULL, `Email` varchar(255) DEFAULT NULL, `Species` enum('Human') NOT NULL DEFAULT 'Human', `CountryID` int NOT NULL DEFAULT '117', `ProvinceID` int NOT NULL, `CityID` int NOT NULL DEFAULT '0', `Address` text, `ZipCode` bigint(10) DEFAULT NULL, `SignupDate` datetime NOT NULL, `LastLogin` datetime DEFAULT NULL, `Confirm` tinyint DEFAULT '0', `Blocked` tinyint(1) NOT NULL DEFAULT '0', `LastChangePass` date DEFAULT NULL, `RegistrationMethod` enum('Web','Internal','API','Developer') DEFAULT NULL, `Checked` tinyint(1) NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `UserRoles` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `RoleID` int NOT NULL, `RoleOption` int NOT NULL DEFAULT '0', `Level` int NOT NULL DEFAULT '1', `StartDate` datetime NOT NULL, `EndDate` datetime DEFAULT NULL, `Confirm` datetime DEFAULT NULL, `AddedBy` int DEFAULT NULL, `IsSuspended` tinyint(1) NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `Events` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `NID` bigint(10) NOT NULL, `TrackingCode` int DEFAULT NULL, `CenterID` int NOT NULL DEFAULT '0', `ServiceID` int NOT NULL, `ContractID` int NOT NULL, `RefID` bigint DEFAULT NULL, `EmdadCheck` bit(1) NOT NULL DEFAULT b'0', `CorporateContractServiceID` int NOT NULL, `UserTariff` int NOT NULL, `EMS` bit(1) NOT NULL DEFAULT b'0', `Level` int NOT NULL, `CenterAdminID` int NOT NULL, `SupervisorID` int NOT NULL, `AcceptorID` int NOT NULL, `AcceptorFee` int NOT NULL, `SecretaryFee` int NOT NULL DEFAULT '0', `AcceptorCodeName` varchar(100) NOT NULL, `AcceptorLevel` tinyint NOT NULL DEFAULT '1', `SupervisorFee` int NOT NULL, `CenterFee` int NOT NULL, `AdminFee` int NOT NULL, `CenterAdminConfirmUserID` int DEFAULT NULL, `CenterAdminConfirmDateTime` datetime DEFAULT NULL, `CenterTechConfirmUserID` int DEFAULT NULL, `CenterTechConfirmDateTime` datetime DEFAULT NULL, `OperatorConfirmUserID` int DEFAULT NULL, `OperatorConfirmDateTime` datetime DEFAULT NULL, `ProvinceSupervisorConfirmUserID` int DEFAULT NULL, `ProvinceSupervisorConfirmDateTime` datetime DEFAULT NULL, `SupervisorConfirmUserID` int DEFAULT NULL, `SupervisorConfirmDateTime` datetime DEFAULT NULL, `StartDate` datetime DEFAULT CURRENT_TIMESTAMP, `EndDate` datetime DEFAULT NULL, `Weight` decimal(10,1) NOT NULL DEFAULT '1.0', `BudgetUsed` tinyint NOT NULL, `BudgetReserved` tinyint NOT NULL, `RejectedByUserID` int DEFAULT NULL, `RejectedAt` datetime DEFAULT NULL, `RejectedComment` text, PRIMARY KEY (`id`));
CREATE TABLE `EventReserves` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int NOT NULL, `UserID` int NOT NULL, `AcceptorID` int NOT NULL, `Date` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `EventsEms` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int NOT NULL, `SecretaryNID` bigint(10) NOT NULL, `EMSType` json DEFAULT NULL, `SuicidalFrom` json DEFAULT NULL, `SuicidalRiskLevel` enum('low','medium','high','norisk') DEFAULT 'norisk', `PsychiatricDisorders` json DEFAULT NULL, `SocialFactors` json DEFAULT NULL, `ProtectiveFactors` json DEFAULT NULL, `SuggestedActions` json DEFAULT NULL, `ActionsTaken` text, `FinancialAssistanceRequest` int NOT NULL DEFAULT '0', `Status` enum('Pending','inProgress','Done','Reject') NOT NULL DEFAULT 'Pending', `DateTime` datetime NOT NULL, `HadPaymentAmount` bigint DEFAULT NULL, `HadPaymentStatus` varchar(20) DEFAULT NULL, `HadPaymentDescription` text, `ConfirmedByUserID` int DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `EventEmsComments` (`id` int NOT NULL AUTO_INCREMENT, `EventEmsID` int NOT NULL, `UserID` int DEFAULT NULL, `Comment` varchar(255) NOT NULL, `Date` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Referrs` (`id` int NOT NULL AUTO_INCREMENT, `RefID` bigint NOT NULL, `UserID` int NOT NULL, `ServiceID` int NOT NULL DEFAULT '0', `Description` text, `Status` enum('Pending','inProgress','Done') NOT NULL DEFAULT 'Pending', `IsReferr` bit(1) NOT NULL DEFAULT b'0', `ProvinceID` int NOT NULL DEFAULT '0', `CityID` int NOT NULL DEFAULT '0', `CenterID` int DEFAULT NULL, `AcceptorID` int DEFAULT NULL, `AdminReferrerID` int DEFAULT NULL, `CreationDate` datetime NOT NULL, `Type` enum('soha','inPerson') NOT NULL DEFAULT 'soha', PRIMARY KEY (`id`));
CREATE TABLE `ReferrsRequest` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `Description` mediumtext, `Status` enum('Pending','inProgress','Done') NOT NULL DEFAULT 'Pending', `ProvinceID` int NOT NULL DEFAULT '0', `CityID` int NOT NULL DEFAULT '0', `CenterID` int DEFAULT NULL, `AdminReferrerID` int DEFAULT NULL, `CreationDate` datetime NOT NULL, `EditionDate` datetime DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `ReferrFollowUps` (`id` int NOT NULL AUTO_INCREMENT, `ReferrID` int NOT NULL, `UserID` int NOT NULL, `Comment` text NOT NULL, `CreatedAt` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Groups` (`id` int NOT NULL AUTO_INCREMENT, `Type` enum('counseling','educational') NOT NULL, `CorporateContractID` int DEFAULT NULL, `CenterID` int NOT NULL, `AcceptorID` int NOT NULL, `CreatorID` int DEFAULT NULL, `Tel` varchar(15) DEFAULT NULL, `Address` varchar(255) NOT NULL, `Status` enum('pending','confirmed','rejected','draft') NOT NULL, `CreateDate` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `GroupEvents` (`id` int NOT NULL AUTO_INCREMENT, `GroupID` int NOT NULL, `Topic` varchar(255) NOT NULL, `Description` varchar(255) DEFAULT NULL, `StartDate` datetime DEFAULT NULL, `EndDate` datetime DEFAULT NULL, `SessionNumber` int DEFAULT NULL, `AcceptorID` int DEFAULT NULL, `AcceptorCodeName` varchar(100) DEFAULT NULL, `AcceptorLevel` tinyint DEFAULT '1', `SupervisorID` int DEFAULT NULL, `CenterAdminID` int DEFAULT NULL, `AcceptorFee` int DEFAULT '0', `SecretaryFee` int NOT NULL DEFAULT '0', `ServiceID` int DEFAULT NULL, `ContractID` int DEFAULT NULL, `UserTariff` int DEFAULT NULL, `BudgetReserved` tinyint NOT NULL DEFAULT '0', `BudgetUsed` tinyint NOT NULL DEFAULT '0', `Weight` decimal(10,1) NOT NULL DEFAULT '1.0', `CenterID` int DEFAULT NULL, `OperatorConfirmUserID` int DEFAULT NULL, `OperatorConfirmDateTime` datetime DEFAULT NULL, `SupervisorConfirmUserID` int DEFAULT NULL, `SupervisorConfirmDateTime` datetime DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `GroupMembers` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `NID` bigint(10) NOT NULL, `GroupID` int NOT NULL, `RefID` bigint DEFAULT NULL, `DateTime` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `GroupEventMember` (`id` bigint NOT NULL AUTO_INCREMENT, `UserID` bigint NOT NULL, `GroupID` bigint NOT NULL, `GroupEventID` bigint DEFAULT NULL, `ServiceID` int DEFAULT NULL, `TrackingCode` int DEFAULT '0', `RefID` bigint DEFAULT NULL, `DateTime` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Budget` (`Id` int NOT NULL AUTO_INCREMENT, `Title` varchar(255) DEFAULT NULL, `Type` enum('Main','Group','Job') DEFAULT NULL, `Amount` decimal(10,1) NOT NULL DEFAULT '0.0', `Remained` decimal(10,1) NOT NULL DEFAULT '0.0', `Reserved` decimal(10,1) NOT NULL DEFAULT '0.0', `StartDate` datetime DEFAULT NULL, `EndDate` datetime DEFAULT NULL, `CreateTime` datetime DEFAULT NULL, `AmountBefore` decimal(10,1) NOT NULL, `Used` decimal(10,1) NOT NULL, `Assigned` decimal(10,1) NOT NULL, PRIMARY KEY (`Id`));
CREATE TABLE `BudgetProvince` (`Id` int NOT NULL AUTO_INCREMENT, `BudgetId` int DEFAULT NULL, `ProvinceId` int DEFAULT NULL, `Amount` decimal(10,1) NOT NULL DEFAULT '0.0', `Remained` decimal(10,1) NOT NULL DEFAULT '0.0', `Reserved` decimal(10,1) NOT NULL DEFAULT '0.0', `CreateTime` datetime DEFAULT NULL, `AmountBefore` decimal(10,1) NOT NULL, `Used` decimal(10,1) NOT NULL, `Assigned` decimal(10,1) NOT NULL, PRIMARY KEY (`Id`));
CREATE TABLE `Incomes` (`id` int NOT NULL AUTO_INCREMENT, `CenterID` int DEFAULT NULL, `UserID` int DEFAULT NULL, `EventID` int DEFAULT NULL, `Type` varchar(50) DEFAULT NULL, `Title` varchar(255) DEFAULT NULL, `Fee` int DEFAULT NULL, `IncomeDate` datetime DEFAULT NULL, `DateTime` datetime DEFAULT NULL, `Description` text, `FileID` varchar(11) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Expenses` (`id` int NOT NULL AUTO_INCREMENT, `CenterID` int DEFAULT NULL, `UserID` int DEFAULT NULL, `Category` varchar(50) DEFAULT NULL, `Type` varchar(100) DEFAULT NULL, `Title` varchar(255) NOT NULL, `PayTo` varchar(100) DEFAULT NULL, `PayType` varchar(50) DEFAULT NULL, `Fee` int DEFAULT NULL, `PayDate` datetime DEFAULT NULL, `DateTime` datetime DEFAULT NULL, `Description` text, `FileID` varchar(11) NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `SMS` (`id` int NOT NULL AUTO_INCREMENT, `SmsSender` int NOT NULL, `SmsReceiver` int NOT NULL, `Number` bigint(11) NOT NULL, `Message` varchar(255) NOT NULL DEFAULT '', `Response` text, `Status` enum('Pending','Failed','Success') NOT NULL DEFAULT 'Pending', `Efforts` int NOT NULL DEFAULT '0', `UpdateTime` datetime NOT NULL, `CreateTime` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Log` (`id` int NOT NULL AUTO_INCREMENT, `uid` int NOT NULL, `Category` varchar(255) DEFAULT NULL, `Description` text, `Level` tinyint NOT NULL DEFAULT '0', `IP` varchar(255) NOT NULL DEFAULT 'UNKNOWN', `Timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
CREATE TABLE `Messages` (`id` int NOT NULL AUTO_INCREMENT, `FromUID` int NOT NULL, `ToUID` int DEFAULT NULL, `Subject` varchar(255) DEFAULT NULL, `Text` text, `FileID` int DEFAULT NULL, `TargetRole` varchar(50) DEFAULT NULL, `TargetProvinceID` int DEFAULT NULL, `Timestamp` datetime NOT NULL, `Star` tinyint(1) NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `Sessions` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `Key` varchar(255) DEFAULT NULL, `IP` varchar(20) DEFAULT NULL, `Browser` varchar(255) DEFAULT NULL, `DateTime` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `ConsultantTax` (`id` int NOT NULL AUTO_INCREMENT, `NID` bigint(10) NOT NULL, `Year` smallint NOT NULL, `Month` tinyint NOT NULL, `TaxAmount` bigint NOT NULL DEFAULT '0', `ExemptionMonths` tinyint NOT NULL DEFAULT '1', `MultiEmployerMonth` tinyint NOT NULL DEFAULT '0', `MultiEmployerYear` tinyint NOT NULL DEFAULT '0', `TotalPayment` bigint NOT NULL DEFAULT '0', `CreatedByUserID` int DEFAULT NULL, `CreatedAt` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `ConsultantEducation` (`id` int NOT NULL AUTO_INCREMENT, `UserID` int NOT NULL, `ConsultantNID` bigint(10) DEFAULT NULL, `Field` varchar(255) DEFAULT NULL, `Orientation` varchar(255) DEFAULT NULL, `Grade` varchar(255) DEFAULT NULL, `Univesity` varchar(255) DEFAULT NULL, `GraduationDate` varchar(25) DEFAULT NULL, `DateTime` datetime DEFAULT CURRENT_TIMESTAMP, `File` varchar(255) DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `InvitePersons` (`ID` int NOT NULL AUTO_INCREMENT, `NID` bigint(10) DEFAULT NULL, `Name` varchar(60) NOT NULL, `Mobile` varchar(12) NOT NULL, `Phone` varchar(12) DEFAULT NULL, `Description` varchar(255) DEFAULT NULL, `Response` varchar(255) DEFAULT NULL, `Status` enum('ارجاع شده','در حال بررسی','اتمام بررسی') NOT NULL, `GroupID` varchar(11) DEFAULT NULL, `GroupName` varchar(255) DEFAULT NULL, `ProvinceID` int DEFAULT NULL, `CityID` int DEFAULT NULL, `CenterID` int DEFAULT NULL, `CreateTime` datetime NOT NULL, `UpdateTime` datetime DEFAULT NULL, PRIMARY KEY (`ID`));
CREATE TABLE `CareerCounseling` (`id` int NOT NULL AUTO_INCREMENT, `RequestStatus` varchar(20) DEFAULT 'در جریان', `ProvinceID` int DEFAULT NULL, `Province` varchar(50) DEFAULT NULL, `Office` varchar(100) DEFAULT NULL, `ApplicantNID` bigint(10) DEFAULT NULL, `ApplicantName` varchar(150) DEFAULT NULL, `ApplicantMobile` bigint(11) DEFAULT NULL, `ApplicantGender` varchar(20) DEFAULT NULL, `TargetGroup` varchar(50) DEFAULT NULL, `ApplicationDate` datetime DEFAULT NULL, `InstituteProvinceID` int DEFAULT NULL, `InstituteProvince` varchar(50) DEFAULT NULL, `Institute` varchar(100) DEFAULT NULL, `ConsultantID` int DEFAULT NULL, `Status` enum('مشاهده نشده','در حال انجام','ثبت شده') DEFAULT 'مشاهده نشده', `CreateDate` datetime DEFAULT NULL, `AgentID` int DEFAULT NULL, `BudgetReserved` tinyint NOT NULL DEFAULT '0', `BudgetUsed` tinyint NOT NULL DEFAULT '0', `Weight` decimal(10,1) NOT NULL DEFAULT '1.0', PRIMARY KEY (`id`));
CREATE TABLE `CorporateContracts` (`id` int NOT NULL AUTO_INCREMENT, `CorporateCustomerID` int NOT NULL, `AppDefault` tinyint NOT NULL DEFAULT '0', `StartDate` datetime NOT NULL, `EndDate` datetime NOT NULL, `Detect` enum('Always','API','NID','Coupon') NOT NULL DEFAULT 'NID', `Remove` tinyint(1) NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `CorporateCustomers` (`id` int NOT NULL AUTO_INCREMENT, `Title` varchar(255) DEFAULT NULL, `Discount` int DEFAULT NULL, `Phone` varchar(50) DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `CorporateContractServices` (`id` int NOT NULL AUTO_INCREMENT, `CorporateContractID` int NOT NULL, `ServiceID` int NOT NULL, `UserTariff` int NOT NULL, `ConsultantLevel1` int NOT NULL DEFAULT '0', `ConsultantLevel2` int NOT NULL DEFAULT '0', `ConsultantLevel3` int NOT NULL DEFAULT '0', `ConsultantLevel4` int NOT NULL DEFAULT '0', `ConsultantLevel5` int NOT NULL DEFAULT '0', `ConsultantDR` int NOT NULL DEFAULT '0', `SecretaryFee` int NOT NULL DEFAULT '0', `SupervisorFee` int NOT NULL DEFAULT '0', `CenterFee` int NOT NULL DEFAULT '0', `AdminFee` int NOT NULL DEFAULT '0', PRIMARY KEY (`id`));
CREATE TABLE `EventPsychology` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int DEFAULT NULL, `UserID` int DEFAULT NULL, `AcceptorID` int DEFAULT NULL, `Job` varchar(255) DEFAULT NULL, `Ethnicity` varchar(255) DEFAULT NULL, `Religion` varchar(255) DEFAULT NULL, `ReligiousBelief` varchar(255) DEFAULT NULL, `Children` int DEFAULT NULL, `ResidenceQuality` text, `SpouseInfo` text, `ProblemStart` text, `ProblemDuration` text, `ClinicalObservation` text, `Appearance` text, `PsychomotorStatus` text, `InterviewAttitude` text, `Mood` text, `Affect` text, `Speech` text, `Perception` text, `ThoughtContent` text, `ThoughtProcess` text, `Consciousness` text, `Orientation` text, `Memory` text, `Concentration` text, `Intelligence` text, `Judgment` text, `Insight` text, `MedicalHistory` text, `FamilyHistory` text, `FamilyRelationships` text, `DateTime` datetime DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
CREATE TABLE `EventComments` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int NOT NULL, `ConsultantNID` bigint(10) NOT NULL, `Comment` text, `DateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
CREATE TABLE `EventNeuroFeedback` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int NOT NULL, `Protocol` varchar(255) DEFAULT NULL, `Target` varchar(255) DEFAULT NULL, `Visible` varchar(255) DEFAULT NULL, `Action` varchar(255) DEFAULT NULL, `Changed` varchar(255) DEFAULT NULL, `EzterabOld` tinyint DEFAULT NULL, `EzterabNew` tinyint DEFAULT NULL, `AfsorOld` tinyint DEFAULT NULL, `AfsorNew` tinyint DEFAULT NULL, `SleepProblemOld` tinyint DEFAULT NULL, `SleepProblemNew` tinyint DEFAULT NULL, `FocusOld` tinyint DEFAULT NULL, `FocusNew` tinyint DEFAULT NULL, `EnergyOld` tinyint DEFAULT NULL, `EnergyNew` tinyint DEFAULT NULL, `Other` varchar(255) DEFAULT NULL, `DateTime` datetime DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
CREATE TABLE `EventHeadMap` (`id` int NOT NULL AUTO_INCREMENT, `EventID` int NOT NULL, `FileID` varchar(255) DEFAULT NULL, `Description` varchar(255) DEFAULT NULL, `DateTime` datetime DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`));
CREATE TABLE `Files` (`id` int NOT NULL AUTO_INCREMENT, `UserNID` bigint(10) NOT NULL, `Name` varchar(255) NOT NULL, `Location` varchar(1024) NOT NULL, `UploadDateTime` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `SpecialOccasions` (`id` int NOT NULL AUTO_INCREMENT, `Title` varchar(255) NOT NULL, `ImagePath` varchar(512) NOT NULL, `DisplayDate` date NOT NULL, `IsActive` tinyint(1) NOT NULL DEFAULT '1', `CreatedByUserID` int DEFAULT NULL, `CreatedAt` datetime NOT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Settings` (`Name` varchar(255) NOT NULL, `Value` varchar(255) DEFAULT NULL, PRIMARY KEY (`Name`));
CREATE TABLE `ApiReports` (`id` int NOT NULL AUTO_INCREMENT, `Type` varchar(255) NOT NULL, `Data` json NOT NULL, `Status` enum('Pending','Failed','Success','Error') NOT NULL DEFAULT 'Pending', `Response` tinytext, `Efforts` tinyint DEFAULT '0', `CreateTime` datetime NOT NULL, `UpdateTime` datetime DEFAULT NULL, PRIMARY KEY (`id`));
CREATE TABLE `Helps` (`id` int NOT NULL AUTO_INCREMENT, `RoleID` int NOT NULL, `File_1` varchar(255) NOT NULL, PRIMARY KEY (`id`));
